import {test} from 'node:test';
import assert from 'node:assert/strict';
import {withRetry} from '../src/retry.mjs';

test('hidden check', async () => {
  const seen = [];
  let attempts = 0;
  const result = await withRetry(async () => { if (attempts++ < 2) throw Object.assign(Error('e' + attempts), {retryable: true}); return 9; }, {sleep: async () => {}, onRetry: (attempt, error) => seen.push([attempt, error.message])});
  assert.equal(result, 9);
  assert.deepEqual(seen, [[0, 'e1'], [1, 'e2']]);
  assert.equal(await withRetry(async () => 1), 1);
});
